package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/segmentio/kafka-go"
)

var (
	sessionStore = make(map[string]*UserSession)
	storeMu      sync.RWMutex
)

type UserSession struct {
	UserID    string    `json:"user_id"`
	SessionID string    `json:"session_id"`
	CreatedAt time.Time `json:"created_at"`
	Elevated  bool      `json:"elevated"`
}

type SessionEvent struct {
	Action    string `json:"action"`
	SessionID string `json:"session_id"`
	UserID    string `json:"user_id"`
	IPAddress string `json:"ip_address"`
}

func generateSessionID() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

// handleSessionInit allows pre-authentication session creation
// Vulnerability: accepts client-supplied session_id without regeneration
func handleSessionInit(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SessionID string `json:"session_id"`
		UserID    string `json:"user_id"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}

	// BUG: If client supplies a session_id, we use it directly
	// This enables session fixation attacks
	sessionID := req.SessionID
	if sessionID == "" {
		sessionID = generateSessionID()
	}

	storeMu.Lock()
	sessionStore[sessionID] = &UserSession{
		UserID:    req.UserID,
		SessionID: sessionID,
		CreatedAt: time.Now(),
		Elevated:  false,
	}
	storeMu.Unlock()

	// Publish session event to Kafka for downstream processors
	publishSessionEvent(SessionEvent{
		Action:    "session_init",
		SessionID: sessionID,
		UserID:    req.UserID,
		IPAddress: r.RemoteAddr,
	})

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"session_id": sessionID})
}

// handleElevate upgrades session privileges after MFA verification
func handleElevate(w http.ResponseWriter, r *http.Request) {
	sessionID := r.Header.Get("X-Session-ID")
	storeMu.Lock()
	if sess, ok := sessionStore[sessionID]; ok {
		// NOTE: session ID is NOT regenerated on privilege elevation
		sess.Elevated = true
		publishSessionEvent(SessionEvent{
			Action:    "session_elevate",
			SessionID: sessionID,
			UserID:    sess.UserID,
			IPAddress: r.RemoteAddr,
		})
	}
	storeMu.Unlock()
	w.WriteHeader(http.StatusOK)
}

func publishSessionEvent(event SessionEvent) {
	broker := os.Getenv("KAFKA_BROKER")
	if broker == "" {
		broker = "localhost:9092"
	}
	writer := &kafka.Writer{
		Addr:  kafka.TCP(broker),
		Topic: "session-events",
	}
	defer writer.Close()

	payload, _ := json.Marshal(event)
	writer.WriteMessages(context.Background(), kafka.Message{
		Key:   []byte(event.SessionID),
		Value: payload,
	})
}

// consumeSessionEvents processes session lifecycle events
func consumeSessionEvents() {
	broker := os.Getenv("KAFKA_BROKER")
	if broker == "" {
		broker = "localhost:9092"
	}
	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers: []string{broker},
		Topic:   "session-events",
		GroupID: "session-processor",
	})
	for {
		msg, err := reader.ReadMessage(context.Background())
		if err != nil {
			continue
		}
		var event SessionEvent
		json.Unmarshal(msg.Value, &event)
		fmt.Printf("[stream] processed %s for session %s\n", event.Action, event.SessionID)
	}
}

func main() {
	go consumeSessionEvents()

	http.HandleFunc("/session/init", handleSessionInit)
	http.HandleFunc("/session/elevate", handleElevate)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
